    @Test
    void anEmptyMonthHasOnlyTheTotal() {
        String csv = new RevenueReport(store).generate(YearMonth.of(2027, 6));

        assertEquals("""
                Pousada Maré Alta,revenue,2027-06
                reservation,room,check_in,check_out,status,amount
                total,0.00
                """, csv);
    }

    @Test
    void tourismTaxListsPaidReservationsStartingInTheMonth() {
        String csv = new TourismTaxReport(store).generate(YearMonth.of(2027, 4));

        // R$ 4.50 per guest per night
        // reservation 1: 1 guest × 2 nights = 9.00
        // reservation 3: 1 guest × 2 nights = 9.00
        // unpaid and refunded cancellations don't count
        assertEquals("""
                Pousada Maré Alta,tourism-tax,2027-04
                reservation,room,check_in,check_out,guests,nights,tax
                1,201,2027-04-01,2027-04-03,1,2,9.00
                3,301,2027-04-02,2027-04-04,1,2,9.00
                total,18.00
                """, csv);
    }

    @Test
    void tourismTaxMultipliesGuestsByNights() {
        Reservation june = book(202, "2027-06-10", "2027-06-13", RatePlan.STANDARD);
        service.confirm(june.id());

        String csv = new TourismTaxReport(store).generate(YearMonth.of(2027, 6));

        // 2 guests × 3 nights × R$ 4.50 = R$ 27.00
        assertEquals("""
                Pousada Maré Alta,tourism-tax,2027-06
                reservation,room,check_in,check_out,guests,nights,tax
                7,202,2027-06-10,2027-06-13,2,3,27.00
                total,27.00
                """, csv);
    }

    @Test
    void ratePlansBreaksDownRevenueByPlan() {
        String csv = new RatePlansReport(store).generate(YearMonth.of(2027, 4));

        // reservation 1 (DELUXE, STANDARD): 779.80
        // reservation 3 (SUITE, STANDARD): 1159.80
        // reservation 2 (STANDARD, NON_REFUNDABLE) starts in March, not April
        assertEquals("""
                Pousada Maré Alta,rate-plans,2027-04
                rate_plan,reservations,amount
                STANDARD,2,1939.60
                NON_REFUNDABLE,0,0.00
                total,2,1939.60
                """, csv);
    }

    @Test
    void ratePlansShowsBothPlansEvenWhenOneIsEmpty() {
        Reservation july = book(101, "2027-07-01", "2027-07-03", RatePlan.NON_REFUNDABLE);
        service.confirm(july.id());

        String csv = new RatePlansReport(store).generate(YearMonth.of(2027, 7));

        assertEquals("""
                Pousada Maré Alta,rate-plans,2027-07
                rate_plan,reservations,amount
                STANDARD,0,0.00
                NON_REFUNDABLE,1,306.00
                total,1,306.00
                """, csv);
    }
}

